### 6.4 Presentation Layer

```typescript
// Extension controller
export class MemoryController {
  constructor(private memoryService: MemoryApplicationService) {}

  async handleStoreMemoryCommand(request: any): Promise<any> {
    try {
      const command = new StoreMemoryCommand(
        request.content,
        request.tags,
        request.context
      );

      const memoryId = await this.memoryService.storeMemory(command);
      return { success: true, memoryId };
    } catch (error) {
      // Error handling
      return { success: false, error: error.message };
